worksheet='''스키마와 구현 설계 작업지\n\n[시나리오]\nID / 이름 / 주체 / 관련 가정:\nBefore:\nSteps:\nAfter:\nMust not:\n대안 분기의 출발 상태:\n\n[가정과 한계]\nID / 종류 / 전제 / 설계 영향 / 재검토 계기:\n한계 / 근거 가정:\n\n[외부 스키마]\nID / 목적 / 사용자 / 입력:\n원본 집합의 선택 조건:\n결과 한 건의 단위:\n필드별 이름 / 타입 / 필수성 / 의미 / 시점 / 원천:\n정렬 / 페이지 / freshness:\n관련 행위 / 수정 정책 / 부재 처리:\n실제 결과 데이터:\n\n[개념 스키마]\n범위 / 외부 참조:\n대상 / 정의 / 동일성 / 수명:\n타입 / 단위 / 값 범위:\n관계 양끝 최소·최대 개수:\n불변식 / 파생식 / 시간 규칙:\n정상·위반 인스턴스:\n\n[행위]\n이름 / 주체 / 입력 / 사전조건:\n사후조건 / 유지되는 사실:\n실패 / 원자성 / 재시도 / 경쟁:\n\n[논리·내부]\n영속화 여부와 근거:\n관계형 구조 / 함수 종속 / 키:\nDB / 타입 / FK / 인덱스 / 동시성 / 보존:\n규칙별 강제 위치 / DDL이 강제하지 않는 규칙:\n실제 SQL / 데이터 / 실행 순서:\n\n[도메인]\n집합체 / 근거 불변식 / 값 / 외부 참조:\n생성 / 복원 / 행위 / 응용 책임 / 저장 계약:\n실행 예 / 실패 예:\n\n[API]\n관점·행위 → 연산 매핑:\n공개 필드 / 입력 권한 / 인증·소유권:\n오류 / 재시도 / 버전 / 페이지:\n완전한 명세 / HTTP 예:\n\n[검증]\n규칙 → 산출물 → 테스트:\n실행한 검증 / 미실행 / 가정이 깨질 때의 변경:\n'''
(ROOT/'worksheet.txt').write_text(worksheet)
nav=''.join('<a href="#'+x['id']+'" data-section="'+x['id']+'"><span class="nav-label">'+x['label']+'</span>'+x['title']+'</a>' for x in chapters)
body=''.join('<section id="'+x['id']+'"><div class="chapter-label">'+x['label']+'</div><h2>'+x['title']+'</h2>'+x['content']+'</section>' for x in chapters)
compiler=(ROOT/'artifacts/compiler.mjs').read_text().replace('export ','')
domain=(ROOT/'artifacts/domain.mjs').read_text().replace('export ','')
js='const ASSETS='+json.dumps(assets,ensure_ascii=False).replace('</','<\\/')+';\nconst WORKSHEET='+json.dumps(worksheet,ensure_ascii=False)+';\n'+compiler+'\n'+domain+'''
function saveFile(filename,text){const u=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
document.querySelectorAll('[data-artifact]').forEach(b=>b.addEventListener('click',()=>saveFile(b.dataset.artifact,ASSETS[b.dataset.artifact])));
let currentSQL='';
function renderGenerator(){const plan=JSON.parse(ASSETS['relational-plan.json']);const policy=JSON.parse(ASSETS['storage-policy.json']);policy.identity=document.getElementById('identity').value;policy.tableStrategy=document.getElementById('storage').value;policy.includeBuyerHistoryIndex=document.getElementById('read-index').checked;if(document.getElementById('missing-rule').checked)delete policy.ruleOwners.R01;const status=document.getElementById('generation-status');try{const r=compile(plan,policy);currentSQL=r.sql;document.getElementById('generated-sql').textContent=r.sql;document.getElementById('trace').textContent=[...r.trace,'',...r.obligations].join('\\n');status.textContent='생성 완료'+' · 미강제 규칙의 구현·검증 책임은 아래에 남습니다.';status.className='';document.getElementById('download-sql').disabled=false;}catch(e){currentSQL='';document.getElementById('generated-sql').textContent='출력 없음';document.getElementById('trace').textContent='입력 정책 또는 생성기 지원을 보완하세요.';status.textContent='생성 중단 · '+e.message;status.className='error';document.getElementById('download-sql').disabled=true;}}
document.querySelectorAll('.controls input,.controls select').forEach(x=>x.addEventListener('change',renderGenerator));document.getElementById('download-sql').addEventListener('click',()=>saveFile('generated-schema.sql',currentSQL));
const ids=JSON.parse(ASSETS['identifiers.json']);const sample=JSON.parse(ASSETS['sample-results.json']);let demoOrder;
function showOrder(message){document.getElementById('domain-status').textContent=message;document.getElementById('domain-result').textContent=JSON.stringify({buyerView:demoOrder.buyerView(ids.buyerA),acceptanceReceipt:demoOrder.acceptanceReceipt()},null,2);}
function resetOrder(){demoOrder=Order.place({id:ids.order,buyerId:ids.buyerA,placedAt:'2026-10-15T01:00:01.000Z',items:sample.submission.body.items,offers:[{productId:ids.bread,name:'우유식빵',unitPriceKrw:3000,offerRevision:'p1-r7',offerable:true},{productId:ids.scone,name:'버터스콘',unitPriceKrw:2000,offerRevision:'p2-r3',offerable:true}]});showOrder('SC01 완료 · PLACED v1, 8,000원');}
document.getElementById('order-reset').addEventListener('click',resetOrder);for(const action of ['cancel','confirm'])document.getElementById('order-'+action).addEventListener('click',()=>{try{demoOrder[action](1);showOrder(action+' 성공 · 저장 전 메모리 상태');}catch(e){showOrder('거부 · '+e.code);}});document.getElementById('order-stranger').addEventListener('click',()=>{try{demoOrder.buyerView(ids.buyerB);}catch(e){document.getElementById('domain-status').textContent='타인 요청 거부 · '+e.code+' (현재 아래 데이터는 소유자 학습 화면입니다.)';}});
const sections=[...document.querySelectorAll('main section')];const search=document.getElementById('search');function filter(){const q=search.value.trim().toLocaleLowerCase();let count=0;for(const s of sections){const match=!q||s.textContent.toLocaleLowerCase().includes(q);s.hidden=!match;document.querySelector('[data-section="'+s.id+'"]').hidden=!match;if(match)count++;}document.getElementById('search-count').textContent=count+' / '+sections.length+'개 장';document.getElementById('empty-search').hidden=count!==0;}search.addEventListener('input',filter);document.getElementById('clear-search').addEventListener('click',()=>{search.value='';filter();});
document.getElementById('expand-all').addEventListener('click',()=>document.querySelectorAll('details').forEach(x=>x.open=true));document.getElementById('collapse-all').addEventListener('click',()=>document.querySelectorAll('details').forEach(x=>x.open=false));document.getElementById('print').addEventListener('click',()=>window.print());
let beforePrint=[];let beforeHidden=[];window.addEventListener('beforeprint',()=>{beforePrint=[...document.querySelectorAll('details')].map(x=>x.open);beforeHidden=sections.map(x=>x.hidden);document.querySelectorAll('details').forEach(x=>x.open=true);sections.forEach(x=>x.hidden=false);});window.addEventListener('afterprint',()=>{document.querySelectorAll('details').forEach((x,i)=>x.open=beforePrint[i]??false);sections.forEach((x,i)=>x.hidden=beforeHidden[i]??false);});
document.querySelectorAll('.checklist input').forEach(x=>x.addEventListener('change',()=>document.getElementById('check-progress').textContent=document.querySelectorAll('.checklist input:checked').length+' / 10 확인'));document.getElementById('download-worksheet').addEventListener('click',()=>saveFile('schema-design-worksheet.txt',WORKSHEET));
renderGenerator();resetOrder();filter();
'''
page='''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="시나리오·가정에서 외부·개념·내부 스키마, 도메인 모델과 API의 완전한 산출물을 도출하는 한국어 설계 교재"><title>시나리오에서 스키마와 구현까지 — 설계 교재</title><style>'''+style+'''</style></head><body><a class="skip" href="#main">본문으로 이동</a><header><div class="hero"><div class="eyebrow">SOFTWARE & DATA MODELING · TEXTBOOK / SECOND EDITION</div><h1>시나리오에서<br>스키마와 구현까지</h1><p class="subtitle">가정과 한계를 기록하고, 표현을 변환하고, 실제 결과를 검산한다.<br>외부·개념·내부 스키마, 도메인 모델, API를 하나의 사례로 완성하는 설계 교재.</p><div class="meta"><span>서론 + 24장</span><span>8개 구체적 시나리오</span><span>12개 가정 · 12개 규칙</span><span>6개 API 연산</span><span>완전한 명세 · SQL · 실행 예제</span></div><div class="hero-actions"><a href="#scenarios">제1장부터 읽기</a><button id="expand-all">명세·풀이 모두 펼치기</button><button id="collapse-all">명세·풀이 접기</button><button id="print">인쇄 / PDF로 저장</button></div><p class="small">전면 개정 · 2026-10-15 · 본문과 실습은 오프라인에서 동작합니다.</p></div></header><div class="layout"><nav aria-label="교재 목차"><strong>학습 경로</strong><label for="search">본문·명세에서 찾기</label><input id="search" type="search" placeholder="예: SC06, 함수 종속, 재시도"><button id="clear-search">검색 해제</button><p id="search-count" role="status"></p><div id="toc-links">'''+nav+'''</div></nav><main id="main"><p id="empty-search" class="empty" hidden>일치하는 장이 없습니다. 검색어를 바꾸거나 검색을 해제하세요.</p>'''+body+'''</main></div><footer>실제 명세와 구현 예제의 보장 범위는 제23장의 검증 명세에 구분해 기록했습니다.</footer><script>'''+js+'''</script></body></html>'''
(ROOT/'index.html').write_text(page)
(ROOT/'artifacts/chapter-index.json').write_text(json.dumps([{k:v for k,v in x.items() if k!='content'} for x in chapters],ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'chapters':len(chapters),'artifactFilesEmbedded':len(assets),'htmlCharacters':len(page),'chapterSourceCharacters':sum(len(x['content']) for x in chapters)},ensure_ascii=False))

# Keep the previously shared entry files synchronized with this edition.
(ROOT/'openapi.json').write_text((ROOT/'artifacts/openapi.json').read_text())
(ROOT/'example.sql').write_text((ROOT/'artifacts/schema.sql').read_text())
(ROOT/'domain-model.mjs').write_text("// Edition 2 entry point.\nexport * from './artifacts/domain.mjs';\n")
(ROOT/'generator.mjs').write_text("// Edition 2: explicit relational plan + policy input.\nexport {compile} from './artifacts/compiler.mjs';\n")
